sys_script.script:
(function executeRule(current, previous /* null when async */) {

    /* =====================================================
       ONLY FOUND ITEMS
    ===================================================== */

    var reportType =
        (
            current.getValue(
                'report_type'
            ) || ''
        )
        .toLowerCase();


    if (reportType !== 'found') {

        /*
         * Lost items can never be in Found-item custody.
         */

        current.setValue(
            'received_at_security_desk',
            false
        );

        current.setValue(
            'received_by',
            ''
        );

        current.setValue(
            'received_on',
            ''
        );

        return;

    }


    /* =====================================================
       JUST RECEIVED
    ===================================================== */

    if (
        current
            .received_at_security_desk
            .changesTo(true)
    ) {

        current.setValue(
            'received_by',
            gs.getUserID()
        );


        current.setValue(
            'received_on',
            new GlideDateTime()
        );

    }


})(current, previous);
